R=/scratch/jjyeung/orch_n30
date -u +%TZ
if tmux has-session -t sb_rlfix 2>/dev/null; then tmux kill-session -t sb_rlfix; echo killed_running_rlfix; { echo sb_rlfix; cat $R/sb_queue/queue.txt; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; fi
echo  | base64 -d > $R/sb_rlfix/prompts/sb_rlfix.md
grep -c "ORCH ANSWER 0620Z" $R/sb_rlfix/prompts/sb_rlfix.md; cat $R/sb_queue/queue.txt | tr "\n" " "; echo; tail -3 $R/sb_queue/codexq.log
pgrep -f "codex_dispatch.sh implement $R/sb_" -a | grep -o "label [a-zA-Z0-9_]*" | sort -u | tr "\n" " "; echo
for t in sb_rowD6 sb_rowB4 sb_posefam sb_ktow sb_kobj sb_roomkit; do d=$(ls -d $R/codex_local/agent/scratch/codex_runs/*_$t 2>/dev/null | tail -1); echo "== $t"; [ -f $d/final_message.md ] && head -c 1200 $d/final_message.md; echo; head -c 250 $R/$t/STATUS.md 2>/dev/null; echo; done
for s in sb_f64; do echo "$s log=$(wc -c < $R/$s/cursor.log)"; ls -t $R/$s/out/evidence | head -3; done
